{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.sru_inward_grading_1 as WITH STORE_REGION AS ( SELECT TRIM(CAST(BRANCH_CODE AS VARCHAR)) AS BRANCH_CODE, MAX(UPPER(TRIM(ZONE))) AS ZONE FROM snitch_db.maplemonk.store_category_delta GROUP BY 1 ), OFFLINE_INV AS ( SELECT UPPER(TRIM(OM.SKU_GROUP)) AS SKU_GROUP, TRIM(CAST(OM.BRANCH_CODE AS VARCHAR)) AS BRANCH_CODE, OM.MARKETPLACE_MAPPED AS STORE_NAME, SR.ZONE AS REGION, COALESCE(OM.TOTAL_SALES, 0) AS SOLD_QTY, COALESCE(OM.INVENTORY, 0) + COALESCE(OM.JIT_QTY, 0) AS CURRENT_INV, COALESCE(OM.TOTAL_SALES, 0) + COALESCE(OM.INVENTORY, 0) + COALESCE(OM.JIT_QTY, 0) AS ALLOCATED_QTY FROM snitch_db.maplemonk.offline_master OM LEFT JOIN STORE_REGION SR ON TRIM(CAST(OM.BRANCH_CODE AS VARCHAR)) = SR.BRANCH_CODE WHERE OM.BRANCH_CODE NOT IN (157,152,146,104,155,123,139,154,120,94,76,98) ), META_MAP AS ( SELECT UPPER(TRIM(M.SKU_GROUP)) AS META_SKU_GROUP, CATEGORY AS CATEGORY_MAPPED, COALESCE( MIN(CASE WHEN UPPER(TRIM(M.L1_CATEGORY)) = \'LONG TAIL\' THEN M.L1_CATEGORY END), MIN(CASE WHEN UPPER(TRIM(M.L1_CATEGORY)) = \'PLUS\' THEN M.L1_CATEGORY END), MIN(CASE WHEN UPPER(TRIM(M.L1_CATEGORY)) = \'LUXE\' THEN M.L1_CATEGORY END), MIN(CASE WHEN UPPER(TRIM(M.L1_CATEGORY)) = \'SNITCH\' THEN M.L1_CATEGORY END), MIN(M.L1_CATEGORY) ) AS L1_CATEGORY, COALESCE( MIN(CASE WHEN UPPER(TRIM(M.CATEGORY)) = \'SHIRTS\' THEN M.CATEGORY END), MIN(CASE WHEN UPPER(TRIM(M.CATEGORY)) IN (\'TSHIRTS\', \'T-SHIRTS\') THEN M.CATEGORY END), MIN(CASE WHEN UPPER(TRIM(M.CATEGORY)) = \'JEANS\' THEN M.CATEGORY END), MIN(CASE WHEN UPPER(TRIM(M.CATEGORY)) = \'TROUSERS\' THEN M.CATEGORY END), MIN(M.CATEGORY) ) AS CATEGORY, COALESCE( MIN(CASE WHEN UPPER(TRIM(M.CATEGORY)) = \'SHIRTS\' THEN M.META1 END), MIN(CASE WHEN UPPER(TRIM(M.CATEGORY)) IN (\'TSHIRTS\', \'T-SHIRTS\') THEN M.META1 END), MIN(CASE WHEN UPPER(TRIM(M.CATEGORY)) = \'JEANS\' THEN M.META1 END), MIN(CASE WHEN UPPER(TRIM(M.CATEGORY)) = \'TROUSERS\' THEN M.META1 END), MIN(M.META1) ) AS META1, COALESCE( MIN(CASE WHEN UPPER(TRIM(M.CATEGORY)) = \'SHIRTS\' THEN M.META2 END), MIN(CASE WHEN UPPER(TRIM(M.CATEGORY)) IN (\'TSHIRTS\', \'T-SHIRTS\') THEN M.META2 END), MIN(CASE WHEN UPPER(TRIM(M.CATEGORY)) = \'JEANS\' THEN M.META2 END), MIN(CASE WHEN UPPER(TRIM(M.CATEGORY)) = \'TROUSERS\' THEN M.META2 END), MIN(M.META2) ) AS META2, COALESCE( MIN(CASE WHEN UPPER(TRIM(M.CATEGORY)) = \'SHIRTS\' THEN M.META3 END), MIN(CASE WHEN UPPER(TRIM(M.CATEGORY)) IN (\'TSHIRTS\', \'T-SHIRTS\') THEN M.META3 END), MIN(CASE WHEN UPPER(TRIM(M.CATEGORY)) = \'JEANS\' THEN M.META3 END), MIN(CASE WHEN UPPER(TRIM(M.CATEGORY)) = \'TROUSERS\' THEN M.META3 END), MIN(M.META3) ) AS META3 FROM snitch_db.maplemonk.meta_mapping_cogs_sku M WHERE M.SKU_GROUP IS NOT NULL GROUP BY UPPER(TRIM(M.SKU_GROUP)), CATEGORY ), PUTAWAY_RAW AS ( SELECT UPPER( TRIM( REVERSE( SUBSTRING( REVERSE(\"Item Type skuCode\"), CHARINDEX(\'-\', REVERSE(\"Item Type skuCode\")) + 1, LEN(\"Item Type skuCode\") ) ) ) ) AS SKU_GROUP, COALESCE( REGEXP_SUBSTR(\"Item Type skuCode\", \'[^-]+$\'), \"Item Type skuCode\" ) AS RAW_SIZE, \"Warehouse Name\" AS FACILITY, CASE WHEN UPPER(TRIM(\"Warehouse Name\")) = \'SAPL-NORTH-TAURU\' THEN \'NORTH\' ELSE \'SOUTH\' END AS REGION, \"PUTAWAY_UPDATED\"::DATE AS INWARD_DATE, SUM(\"PUTAWAY_COMPLETED_QUANTITY\") AS QTY FROM snitch_db.maplemonk.putaway_tracking WHERE \"PUTAWAY_UPDATED\"::DATE >= \'2025-12-31\' AND LOWER(FINAL_TYPE) LIKE \'new%\' GROUP BY 1,2,3,4,5 ), PUTAWAY_MAPPED AS ( SELECT *, CASE WHEN SKU_GROUP LIKE \'SN0%\' OR SKU_GROUP LIKE \'4MSFR%\' OR SKU_GROUP LIKE \'BP%\' THEN \'NA\' WHEN SKU_GROUP LIKE \'SH0%\' THEN CASE WHEN RAW_SIZE = \'39\' THEN \'XS\' WHEN RAW_SIZE = \'40\' THEN \'S\' WHEN RAW_SIZE = \'41\' THEN \'M\' WHEN RAW_SIZE = \'42\' THEN \'L\' WHEN RAW_SIZE = \'43\' THEN \'XL\' WHEN RAW_SIZE = \'44\' THEN \'XXL\' WHEN RAW_SIZE = \'45\' THEN \'3XL\' ELSE RAW_SIZE END ELSE CASE WHEN RAW_SIZE = \'28\' THEN \'XS\' WHEN RAW_SIZE = \'30\' THEN \'S\' WHEN RAW_SIZE = \'32\' THEN \'M\' WHEN RAW_SIZE = \'34\' THEN \'L\' WHEN RAW_SIZE = \'36\' THEN \'XL\' WHEN RAW_SIZE = \'38\' THEN \'XXL\' WHEN RAW_SIZE = \'40\' THEN \'3XL\' WHEN RAW_SIZE = \'42\' THEN \'4XL\' WHEN RAW_SIZE = \'44\' THEN \'5XL\' WHEN RAW_SIZE = \'46\' THEN \'6XL\' WHEN RAW_SIZE = \'48\' THEN \'7XL\' WHEN RAW_SIZE = \'50\' THEN \'8XL\' WHEN RAW_SIZE IS NULL OR RAW_SIZE = \'\' THEN \'NA\' ELSE RAW_SIZE END END AS SIZE_MAPPED FROM PUTAWAY_RAW ), INWARD_BASE AS ( SELECT P.SKU_GROUP, MAX(P.INWARD_DATE) AS LATEST_INWARD_DATE, SUM(CASE WHEN SIZE_MAPPED = \'S\' THEN QTY ELSE 0 END) AS S_QTY, SUM(CASE WHEN SIZE_MAPPED = \'M\' THEN QTY ELSE 0 END) AS M_QTY, SUM(CASE WHEN SIZE_MAPPED = \'L\' THEN QTY ELSE 0 END) AS L_QTY, SUM(CASE WHEN SIZE_MAPPED = \'XL\' THEN QTY ELSE 0 END) AS XL_QTY, SUM(CASE WHEN SIZE_MAPPED = \'3XL\' THEN QTY ELSE 0 END) AS XL3_QTY, SUM(CASE WHEN SIZE_MAPPED = \'4XL\' THEN QTY ELSE 0 END) AS XL4_QTY, SUM(CASE WHEN SIZE_MAPPED = \'5XL\' THEN QTY ELSE 0 END) AS XL5_QTY, SUM(CASE WHEN SIZE_MAPPED = \'6XL\' THEN QTY ELSE 0 END) AS XL6_QTY FROM PUTAWAY_MAPPED P GROUP BY 1 ), INWARD_FULL_SETS AS ( SELECT IB.*, MM.CATEGORY_MAPPED, MM.L1_CATEGORY, CASE WHEN UPPER(TRIM(MM.L1_CATEGORY)) = \'PLUS\' THEN LEAST( FLOOR(COALESCE(XL3_QTY,0) / 3), FLOOR(COALESCE(XL4_QTY,0) / 3), FLOOR(COALESCE(XL5_QTY,0) / 2), FLOOR(COALESCE(XL6_QTY,0) / 2) ) ELSE LEAST( FLOOR(COALESCE(S_QTY,0) / 3), FLOOR(COALESCE(M_QTY,0) / 4), FLOOR(COALESCE(L_QTY,0) / 4), FLOOR(COALESCE(XL_QTY,0) / 3) ) END AS INWARDED_FULL_SET_COUNT FROM INWARD_BASE IB LEFT JOIN META_MAP MM ON UPPER(TRIM(IB.SKU_GROUP)) = MM.META_SKU_GROUP ), INWARD_FINAL AS ( SELECT *, INWARDED_FULL_SET_COUNT * CASE WHEN UPPER(TRIM(L1_CATEGORY)) = \'PLUS\' THEN 10 ELSE 14 END AS INWARDED_FULL_SET_QTY FROM INWARD_FULL_SETS ), STORE_COUNT AS ( SELECT COUNT(DISTINCT BRANCH_CODE) AS TOTAL_STORE_COUNT FROM OFFLINE_INV ), WH_BASE AS ( SELECT UPPER(TRIM(SKU_GROUP)) AS SKU_GROUP, SUM(COALESCE(XS_UNITS,0)) AS XS_UNITS, SUM(COALESCE(S_UNITS,0)) AS S_UNITS, SUM(COALESCE(M_UNITS,0)) AS M_UNITS, SUM(COALESCE(L_UNITS,0)) AS L_UNITS, SUM(COALESCE(XL_UNITS,0)) AS XL_UNITS, SUM(COALESCE(XXL_UNITS,0)) AS XXL_UNITS, SUM(COALESCE(XL3_UNITS,0)) AS XL3_UNITS, SUM(COALESCE(XL4_UNITS,0)) AS XL4_UNITS, SUM(COALESCE(XL5_UNITS,0)) AS XL5_UNITS, SUM(COALESCE(XL6_UNITS,0)) AS XL6_UNITS, SUM(COALESCE(XL7_UNITS,0)) AS XL7_UNITS, SUM(COALESCE(XL8_UNITS,0)) AS XL8_UNITS FROM snitch_db.maplemonk.availability_master_v2_merged GROUP BY 1 ), WH_CALC AS ( SELECT WB.*, MM.CATEGORY_MAPPED, MM.L1_CATEGORY, ( COALESCE(XS_UNITS,0) + COALESCE(S_UNITS,0) + COALESCE(M_UNITS,0) + COALESCE(L_UNITS,0) + COALESCE(XL_UNITS,0) + COALESCE(XXL_UNITS,0) + COALESCE(XL3_UNITS,0) + COALESCE(XL4_UNITS,0) + COALESCE(XL5_UNITS,0) + COALESCE(XL6_UNITS,0) + COALESCE(XL7_UNITS,0) + COALESCE(XL8_UNITS,0) ) AS CURRENT_WH_INV, CASE WHEN UPPER(TRIM(MM.L1_CATEGORY)) = \'PLUS\' OR WB.SKU_GROUP LIKE \'4MBG%\' OR WB.SKU_GROUP LIKE \'4BRN%\' OR WB.SKU_GROUP LIKE \'4BPL%\' OR WB.SKU_GROUP LIKE \'4BTR%\' OR WB.SKU_GROUP LIKE \'4BCH%\' OR WB.SKU_GROUP LIKE \'4BJE%\' OR WB.SKU_GROUP LIKE \'4BJK%\' OR WB.SKU_GROUP LIKE \'4BSW%\' OR WB.SKU_GROUP LIKE \'4BHD%\' OR WB.SKU_GROUP LIKE \'4BOS%\' OR WB.SKU_GROUP LIKE \'4BSHS%\' OR WB.SKU_GROUP LIKE \'4BSFS%\' OR WB.SKU_GROUP LIKE \'4BSH%\' OR WB.SKU_GROUP LIKE \'4BBL%\' OR WB.SKU_GROUP LIKE \'4BCA%\' OR WB.SKU_GROUP LIKE \'4BSWT%\' OR WB.SKU_GROUP LIKE \'4BCD%\' OR WB.SKU_GROUP LIKE \'4BJO%\' THEN LEAST( FLOOR(COALESCE(XL3_UNITS,0) / 3), FLOOR(COALESCE(XL4_UNITS,0) / 3), FLOOR(COALESCE(XL5_UNITS,0) / 2), FLOOR(COALESCE(XL6_UNITS,0) / 2) ) ELSE LEAST( FLOOR(COALESCE(S_UNITS,0) / 3), FLOOR(COALESCE(M_UNITS,0) / 4), FLOOR(COALESCE(L_UNITS,0) / 4), FLOOR(COALESCE(XL_UNITS,0) / 3) ) END AS CURRENT_WH_FULL_SET_COUNT FROM WH_BASE WB LEFT JOIN META_MAP MM ON WB.SKU_GROUP = MM.META_SKU_GROUP ), WH_FINAL AS ( SELECT *, CURRENT_WH_FULL_SET_COUNT * CASE WHEN UPPER(TRIM(L1_CATEGORY)) = \'PLUS\' OR SKU_GROUP LIKE \'4MBG%\' OR SKU_GROUP LIKE \'4BRN%\' OR SKU_GROUP LIKE \'4BPL%\' OR SKU_GROUP LIKE \'4BTR%\' OR SKU_GROUP LIKE \'4BCH%\' OR SKU_GROUP LIKE \'4BJE%\' OR SKU_GROUP LIKE \'4BJK%\' OR SKU_GROUP LIKE \'4BSW%\' OR SKU_GROUP LIKE \'4BHD%\' OR SKU_GROUP LIKE \'4BOS%\' OR SKU_GROUP LIKE \'4BSHS%\' OR SKU_GROUP LIKE \'4BSFS%\' OR SKU_GROUP LIKE \'4BSH%\' OR SKU_GROUP LIKE \'4BBL%\' OR SKU_GROUP LIKE \'4BCA%\' OR SKU_GROUP LIKE \'4BSWT%\' OR SKU_GROUP LIKE \'4BCD%\' OR SKU_GROUP LIKE \'4BJO%\' THEN 10 ELSE 14 END AS CURRENT_WH_FULL_SIZE_QTY, GREATEST( CURRENT_WH_INV - ( CURRENT_WH_FULL_SET_COUNT * CASE WHEN UPPER(TRIM(L1_CATEGORY)) = \'PLUS\' OR SKU_GROUP LIKE \'4MBG%\' OR SKU_GROUP LIKE \'4BRN%\' OR SKU_GROUP LIKE \'4BPL%\' OR SKU_GROUP LIKE \'4BTR%\' OR SKU_GROUP LIKE \'4BCH%\' OR SKU_GROUP LIKE \'4BJE%\' OR SKU_GROUP LIKE \'4BJK%\' OR SKU_GROUP LIKE \'4BSW%\' OR SKU_GROUP LIKE \'4BHD%\' OR SKU_GROUP LIKE \'4BOS%\' OR SKU_GROUP LIKE \'4BSHS%\' OR SKU_GROUP LIKE \'4BSFS%\' OR SKU_GROUP LIKE \'4BSH%\' OR SKU_GROUP LIKE \'4BBL%\' OR SKU_GROUP LIKE \'4BCA%\' OR SKU_GROUP LIKE \'4BSWT%\' OR SKU_GROUP LIKE \'4BCD%\' OR SKU_GROUP LIKE \'4BJO%\' THEN 10 ELSE 14 END ), 0 ) AS CURRENT_WH_CUT_SIZE_QTY FROM WH_CALC ) SELECT OI.BRANCH_CODE, OI.STORE_NAME, OI.REGION, OI.SKU_GROUP, MM.CATEGORY_MAPPED AS CATEGORY, MM.L1_CATEGORY AS L1_CAT, MM.META1 AS META_1, MM.META2 AS META_2, MM.META3 AS META_3, COALESCE( IFN.INWARDED_FULL_SET_QTY, 0 ) AS INWARDED_FULL_SETS_QTY, COALESCE( IFN.INWARDED_FULL_SET_COUNT, 0 ) AS INWARDED_FULL_SIZE_SETS, SC.TOTAL_STORE_COUNT, FLOOR( COALESCE(IFN.INWARDED_FULL_SET_COUNT, 0) * 0.75 ) AS ALLOCATABLE_INWARDED_SIZE_SETS, CASE WHEN SC.TOTAL_STORE_COUNT = 0 THEN NULL WHEN FLOOR( COALESCE(IFN.INWARDED_FULL_SET_COUNT, 0) * 0.75 ) >= SC.TOTAL_STORE_COUNT THEN \'A\' WHEN FLOOR( COALESCE(IFN.INWARDED_FULL_SET_COUNT, 0) * 0.75 ) >= SC.TOTAL_STORE_COUNT * 0.75 THEN \'B\' WHEN FLOOR( COALESCE(IFN.INWARDED_FULL_SET_COUNT, 0) * 0.75 ) >= SC.TOTAL_STORE_COUNT * 0.50 THEN \'C\' ELSE \'D\' END AS INWARD_SKU_GRADE, OI.ALLOCATED_QTY AS ALLOCATED_QTY_STORE, OI.SOLD_QTY AS SOLD_QTY, OI.CURRENT_INV AS CURRENT_STORE_INV, COALESCE( WH.CURRENT_WH_INV, 0 ) AS CURRENT_WH_INV, COALESCE( WH.CURRENT_WH_FULL_SET_COUNT, 0 ) AS CURRENT_WH_FULL_SET_COUNT, COALESCE( WH.CURRENT_WH_FULL_SIZE_QTY, 0 ) AS CURRENT_WH_FULL_SIZE_QTY, COALESCE( WH.CURRENT_WH_CUT_SIZE_QTY, 0 ) AS CURRENT_WH_CUT_SIZE_QTY FROM OFFLINE_INV OI LEFT JOIN META_MAP MM ON OI.SKU_GROUP = MM.META_SKU_GROUP LEFT JOIN INWARD_FINAL IFN ON OI.SKU_GROUP = IFN.SKU_GROUP LEFT JOIN WH_FINAL WH ON OI.SKU_GROUP = WH.SKU_GROUP CROSS JOIN STORE_COUNT SC ORDER BY OI.REGION, OI.STORE_NAME, OI.SKU_GROUP; create or replace table snitch_db.maplemonk.sru_mrp_bucket_grading as WITH STORE_REGION AS ( SELECT TRIM(CAST(BRANCH_CODE AS VARCHAR)) AS BRANCH_CODE, MAX(UPPER(TRIM(ZONE))) AS ZONE FROM snitch_db.maplemonk.store_category_delta GROUP BY 1 ), OFFLINE_INV AS ( SELECT UPPER(TRIM(OM.SKU_GROUP)) AS SKU_GROUP, TRIM(CAST(OM.BRANCH_CODE AS VARCHAR)) AS BRANCH_CODE, OM.MARKETPLACE_MAPPED AS STORE_NAME, SR.ZONE AS REGION, COALESCE(OM.TOTAL_SALES, 0) AS total_SOLD_QTY, COALESCE(OM.INVENTORY, 0) + COALESCE(OM.JIT_QTY, 0) AS CURRENT_INV, COALESCE(OM.TOTAL_SALES, 0) + COALESCE(OM.INVENTORY, 0) + COALESCE(OM.JIT_QTY, 0) AS ALLOCATED_QTY FROM snitch_db.maplemonk.offline_master OM LEFT JOIN STORE_REGION SR ON TRIM(CAST(OM.BRANCH_CODE AS VARCHAR)) = SR.BRANCH_CODE WHERE OM.BRANCH_CODE NOT IN (157,152,146,104,155,123,139,154,120, 94, 76,98) ), META_MAP AS ( SELECT UPPER(TRIM(M.SKU_GROUP)) AS META_SKU_GROUP, CATEGORY AS CATEGORY_MAPPED, COALESCE( MIN(CASE WHEN UPPER(TRIM(M.L1_CATEGORY)) = \'LONG TAIL\' THEN M.L1_CATEGORY END), MIN(CASE WHEN UPPER(TRIM(M.L1_CATEGORY)) = \'PLUS\' THEN M.L1_CATEGORY END), MIN(CASE WHEN UPPER(TRIM(M.L1_CATEGORY)) = \'LUXE\' THEN M.L1_CATEGORY END), MIN(CASE WHEN UPPER(TRIM(M.L1_CATEGORY)) = \'SNITCH\' THEN M.L1_CATEGORY END), MIN(M.L1_CATEGORY) ) AS L1_CATEGORY, COALESCE( MIN(CASE WHEN UPPER(TRIM(M.CATEGORY)) = \'SHIRTS\' THEN M.CATEGORY END), MIN(CASE WHEN UPPER(TRIM(M.CATEGORY)) IN (\'TSHIRTS\', \'T-SHIRTS\') THEN M.CATEGORY END), MIN(CASE WHEN UPPER(TRIM(M.CATEGORY)) = \'JEANS\' THEN M.CATEGORY END), MIN(CASE WHEN UPPER(TRIM(M.CATEGORY)) = \'TROUSERS\' THEN M.CATEGORY END), MIN(M.CATEGORY) ) AS CATEGORY, COALESCE( MIN(CASE WHEN UPPER(TRIM(M.CATEGORY)) = \'SHIRTS\' THEN M.META1 END), MIN(CASE WHEN UPPER(TRIM(M.CATEGORY)) IN (\'TSHIRTS\', \'T-SHIRTS\') THEN M.META1 END), MIN(CASE WHEN UPPER(TRIM(M.CATEGORY)) = \'JEANS\' THEN M.META1 END), MIN(CASE WHEN UPPER(TRIM(M.CATEGORY)) = \'TROUSERS\' THEN M.META1 END), MIN(M.META1) ) AS META1, COALESCE( MIN(CASE WHEN UPPER(TRIM(M.CATEGORY)) = \'SHIRTS\' THEN M.META2 END), MIN(CASE WHEN UPPER(TRIM(M.CATEGORY)) IN (\'TSHIRTS\', \'T-SHIRTS\') THEN M.META2 END), MIN(CASE WHEN UPPER(TRIM(M.CATEGORY)) = \'JEANS\' THEN M.META2 END), MIN(CASE WHEN UPPER(TRIM(M.CATEGORY)) = \'TROUSERS\' THEN M.META2 END), MIN(M.META2) ) AS META2, COALESCE( MIN(CASE WHEN UPPER(TRIM(M.CATEGORY)) = \'SHIRTS\' THEN M.META3 END), MIN(CASE WHEN UPPER(TRIM(M.CATEGORY)) IN (\'TSHIRTS\', \'T-SHIRTS\') THEN M.META3 END), MIN(CASE WHEN UPPER(TRIM(M.CATEGORY)) = \'JEANS\' THEN M.META3 END), MIN(CASE WHEN UPPER(TRIM(M.CATEGORY)) = \'TROUSERS\' THEN M.META3 END), MIN(M.META3) ) AS META3 FROM snitch_db.maplemonk.meta_mapping_cogs_sku M WHERE M.SKU_GROUP IS NOT NULL GROUP BY UPPER(TRIM(M.SKU_GROUP)), CATEGORY ), sales_non_eoss_base AS ( SELECT TRIM(CAST(BRANCH_CODE AS VARCHAR)) AS BRANCH_CODE, MAX(marketplace_mapped) AS marketplace_mapped, UPPER(TRIM(sku_group)) AS sku_group, MAX(MRP) AS MRP, SUM(SUBORDER_QUANTITY) AS qty_sold, SUM(selling_price) AS revenue FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE WHERE order_date >= \'2026-01-01\' AND order_date NOT BETWEEN \'2026-01-01\' AND \'2026-01-31\' AND order_date NOT BETWEEN \'2026-06-26\' AND \'2026-07-31\' AND BRANCH_CODE NOT IN ( 2, 8, 9, 10, 32, 33, 35, 45, 46, 59, 60, 76, 94, 95, 98, 148 ) AND doc_prefix NOT IN (\'OMS\', \'QCOM\') AND sku NOT LIKE \'%CB%\' AND sku NOT LIKE \'8909%\' AND sku NOT LIKE \'NT0%\' AND sku NOT LIKE \'%UNIFORM%\' AND sku NOT LIKE \'%GIFT%\' GROUP BY TRIM(CAST(BRANCH_CODE AS VARCHAR)), UPPER(TRIM(sku_group)) ), LOGIC_MRP AS ( SELECT UPPER(TRIM( CASE WHEN POSITION(\'-\' IN SKU) > 0 THEN LEFT( SKU, LENGTH(SKU) - LENGTH(REVERSE(SUBSTRING(REVERSE(SKU), 1, POSITION(\'-\', REVERSE(SKU)) - 1))) - 1 ) ELSE SKU END )) AS SKU_GROUP, MAX(MRP) AS MRP FROM snitch_db.maplemonk.logic_final_item_master GROUP BY 1 ), sales_non_eoss AS ( SELECT BRANCH_CODE, marketplace_mapped, sku_group, MRP, CASE WHEN MRP IS NULL THEN \'UNKNOWN\' WHEN MRP <= 500 THEN \'0-500\' ELSE CONCAT( (CEIL(MRP / 500.0) - 1) * 500, \'-\', CEIL(MRP / 500.0) * 500 ) END AS MRP_BUCKET, qty_sold, revenue FROM sales_non_eoss_base ), BASE_PRODUCT AS ( SELECT UPPER(TRIM(SKU_GROUP)) AS SKU_GROUP, MAX(FINAL_LIVE_DATE) AS FINAL_LIVE_DATE FROM snitch_db.maplemonk.base_product GROUP BY 1 ), all_joined as ( select oi.*, CASE WHEN BP.FINAL_LIVE_DATE IS NULL THEN \'DRAFT\' ELSE TO_VARCHAR(BP.FINAL_LIVE_DATE) END AS LIVE_DATE, mm.category_mapped, mm.L1_category, mm.category, mm.meta1, mm.meta2, mm.meta3, COALESCE(sne.MRP, LM.MRP) AS MRP, CASE WHEN COALESCE(sne.MRP, LM.MRP) IS NULL THEN \'UNKNOWN\' WHEN COALESCE(sne.MRP, LM.MRP) <= 500 THEN \'0-500\' ELSE CONCAT((CEIL(COALESCE(sne.MRP, LM.MRP) / 500.0) - 1) * 500, \'-\', CEIL(COALESCE(sne.MRP, LM.MRP) / 500.0) * 500) END AS MRP_BUCKET, sne.qty_sold as qty_sold, sne.revenue as revenue from OFFLINE_INV oi left join meta_map mm on oi.sku_group = mm.meta_sku_group left join sales_non_eoss sne on oi.branch_code = sne.branch_code and oi.sku_group = sne.sku_group LEFT JOIN BASE_PRODUCT BP ON oi.SKU_GROUP = BP.SKU_GROUP LEFT JOIN LOGIC_MRP LM ON oi.SKU_GROUP = LM.SKU_GROUP ), GRAIN_MRP_REVENUE AS ( SELECT BRANCH_CODE, MAX(STORE_NAME) AS STORE_NAME, MAX(REGION) AS REGION, CATEGORY_MAPPED, L1_CATEGORY, META1, META2, META3, MRP_BUCKET, SUM(COALESCE(QTY_SOLD, 0)) AS QTY_SOLD, SUM(COALESCE(REVENUE, 0)) AS REVENUE FROM ALL_JOINED WHERE MRP_BUCKET IS NOT NULL GROUP BY BRANCH_CODE, CATEGORY_MAPPED, L1_CATEGORY, META1, META2, META3, MRP_BUCKET ), GRAIN_TOTAL AS ( SELECT *, SUM(REVENUE) OVER ( PARTITION BY BRANCH_CODE, CATEGORY_MAPPED, L1_CATEGORY, META1, META2, META3 ) AS TOTAL_GRAIN_REVENUE FROM GRAIN_MRP_REVENUE ), MRP_RANKING AS ( SELECT *, ROW_NUMBER() OVER ( PARTITION BY BRANCH_CODE, CATEGORY_MAPPED, L1_CATEGORY, META1, META2, META3 ORDER BY REVENUE DESC, MRP_BUCKET ) AS MRP_REVENUE_RANK, REVENUE / NULLIF(TOTAL_GRAIN_REVENUE, 0) AS REVENUE_SHARE FROM GRAIN_TOTAL ), PARETO AS ( SELECT *, SUM(REVENUE) OVER ( PARTITION BY BRANCH_CODE, CATEGORY_MAPPED, L1_CATEGORY, META1, META2, META3 ORDER BY REVENUE DESC, MRP_BUCKET ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) / NULLIF(TOTAL_GRAIN_REVENUE, 0) AS CUMULATIVE_REVENUE_SHARE, ( SUM(REVENUE) OVER ( PARTITION BY BRANCH_CODE, CATEGORY_MAPPED, L1_CATEGORY, META1, META2, META3 ORDER BY REVENUE DESC, MRP_BUCKET ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) - REVENUE ) / NULLIF(TOTAL_GRAIN_REVENUE, 0) AS PREVIOUS_CUMULATIVE_REVENUE_SHARE FROM MRP_RANKING ), FINAL_GRADE AS ( SELECT *, CASE WHEN COALESCE(PREVIOUS_CUMULATIVE_REVENUE_SHARE, 0) < 0.25 THEN \'A\' WHEN COALESCE(PREVIOUS_CUMULATIVE_REVENUE_SHARE, 0) < 0.50 THEN \'B\' WHEN COALESCE(PREVIOUS_CUMULATIVE_REVENUE_SHARE, 0) < 0.75 THEN \'C\' ELSE \'D\' END AS MRP_BUCKET_GRADE FROM PARETO ), GRADE_MAPPING AS ( SELECT DISTINCT BRANCH_CODE, CATEGORY_MAPPED, L1_CATEGORY, META1, META2, META3, MRP_BUCKET, MRP_BUCKET_GRADE FROM FINAL_GRADE WHERE REVENUE > 0 ), SKU_GRADE_MAPPING AS ( SELECT AJ.BRANCH_CODE, AJ.STORE_NAME, AJ.REGION, AJ.SKU_GROUP, AJ.LIVE_DATE, AJ.TOTAL_SOLD_QTY, AJ.CURRENT_INV, AJ.ALLOCATED_QTY, AJ.CATEGORY_MAPPED, AJ.L1_CATEGORY, AJ.CATEGORY, AJ.META1, AJ.META2, AJ.META3, AJ.MRP, AJ.MRP_BUCKET, COALESCE(GM.MRP_BUCKET_GRADE, \'D\') AS MRP_BUCKET_GRADE FROM ALL_JOINED AJ LEFT JOIN GRADE_MAPPING GM ON AJ.BRANCH_CODE = GM.BRANCH_CODE AND EQUAL_NULL(AJ.CATEGORY_MAPPED, GM.CATEGORY_MAPPED) AND EQUAL_NULL(AJ.L1_CATEGORY, GM.L1_CATEGORY) AND EQUAL_NULL(AJ.META1, GM.META1) AND EQUAL_NULL(AJ.META2, GM.META2) AND EQUAL_NULL(AJ.META3, GM.META3) AND EQUAL_NULL(AJ.MRP_BUCKET, GM.MRP_BUCKET) ) SELECT * FROM SKU_GRADE_MAPPING where L1_CATEGORY in (\'snitch\', \'plus\', \'luxe\') and lower(SKU_GROUP) not like \'%gift%\' ORDER BY BRANCH_CODE, CATEGORY_MAPPED, L1_CATEGORY, META1, META2, META3, SKU_GROUP ; create or replace table snitch_db.maplemonk.offline_grading_final_pivot as WITH inward_grading AS ( SELECT BRANCH_CODE, STORE_NAME, REGION, SKU_GROUP, CATEGORY, L1_CAT, META_1, META_2, META_3, INWARDED_FULL_SETS_QTY, INWARDED_FULL_SIZE_SETS, ALLOCATED_QTY_STORE, SOLD_QTY, CURRENT_STORE_INV, CURRENT_WH_INV, CURRENT_WH_FULL_SET_COUNT, CURRENT_WH_FULL_SIZE_QTY, CURRENT_WH_CUT_SIZE_QTY, INWARD_SKU_GRADE FROM snitch_db.maplemonk.sru_inward_grading_1 WHERE L1_CAT IN (\'snitch\', \'plus\', \'luxe\') QUALIFY ROW_NUMBER() OVER ( PARTITION BY TRIM(CAST(BRANCH_CODE AS VARCHAR)), UPPER(TRIM(SKU_GROUP)) ORDER BY SKU_GROUP ) = 1 ), mrp_bucket_grading AS ( SELECT BRANCH_CODE, SKU_GROUP, LIVE_DATE, CATEGORY_MAPPED, L1_CATEGORY, META1, META2, META3, MRP, MRP_BUCKET, MRP_BUCKET_GRADE FROM snitch_db.maplemonk.sru_mrp_bucket_grading QUALIFY ROW_NUMBER() OVER ( PARTITION BY TRIM(CAST(BRANCH_CODE AS VARCHAR)), UPPER(TRIM(SKU_GROUP)) ORDER BY LIVE_DATE DESC NULLS LAST ) = 1 ), mrp_store_grain_base AS ( SELECT BRANCH_CODE, LOWER(TRIM(CATEGORY_MAPPED)) AS CATEGORY, LOWER(TRIM(L1_CATEGORY)) AS L1_CATEGORY, CASE WHEN META1 IS NULL OR TRIM(META1) = \'\' THEN NULL ELSE LOWER(TRIM(META1)) END AS META1, CASE WHEN META2 IS NULL OR TRIM(META2) = \'\' THEN NULL ELSE LOWER(TRIM(META2)) END AS META2, CASE WHEN META3 IS NULL OR TRIM(META3) = \'\' THEN NULL ELSE LOWER(TRIM(META3)) END AS META3, MRP_BUCKET, MRP_BUCKET_GRADE, LIVE_DATE FROM snitch_db.maplemonk.sru_mrp_bucket_grading ), mrp_store_grain AS ( SELECT BRANCH_CODE, CATEGORY, L1_CATEGORY, META1, META2, META3, MRP_BUCKET, MRP_BUCKET_GRADE FROM mrp_store_grain_base QUALIFY ROW_NUMBER() OVER ( PARTITION BY TRIM(CAST(BRANCH_CODE AS VARCHAR)), CATEGORY, L1_CATEGORY, COALESCE(META1, \'__NULL__\'), COALESCE(META2, \'__NULL__\'), COALESCE(META3, \'__NULL__\'), MRP_BUCKET ORDER BY LIVE_DATE DESC NULLS LAST ) = 1 ), grain_grading_base AS ( SELECT BRANCH_CODE, LOWER(TRIM(CATEGORY)) AS CATEGORY, CASE WHEN META1 IS NULL OR TRIM(META1) = \'\' OR LOWER(TRIM(META1)) = \'unmapped\' THEN NULL ELSE LOWER(TRIM(META1)) END AS META1, CASE WHEN META2 IS NULL OR TRIM(META2) = \'\' OR LOWER(TRIM(META2)) = \'unmapped\' THEN NULL ELSE LOWER(TRIM(META2)) END AS META2, CASE WHEN META3 IS NULL OR TRIM(META3) = \'\' OR LOWER(TRIM(META3)) = \'unmapped\' THEN NULL ELSE LOWER(TRIM(META3)) END AS META3, GRADE FROM snitch_db.maplemonk.gs__offline_grading ), grain_grading AS ( SELECT BRANCH_CODE, CATEGORY, META1, META2, META3, GRADE FROM grain_grading_base QUALIFY ROW_NUMBER() OVER ( PARTITION BY TRIM(CAST(BRANCH_CODE AS VARCHAR)), CATEGORY, COALESCE(META1, \'__NULL__\'), COALESCE(META2, \'__NULL__\'), COALESCE(META3, \'__NULL__\') ORDER BY CASE UPPER(TRIM(GRADE)) WHEN \'A\' THEN 1 WHEN \'B\' THEN 2 WHEN \'C\' THEN 3 WHEN \'D\' THEN 4 ELSE 5 END ) = 1 ), final_base AS ( SELECT IG.BRANCH_CODE, IG.STORE_NAME, IG.REGION, IG.SKU_GROUP, IG.CATEGORY, MG.MRP_BUCKET, MG.LIVE_DATE, IG.L1_CAT, IG.META_1, IG.META_2, IG.META_3, IG.INWARDED_FULL_SETS_QTY, IG.INWARDED_FULL_SIZE_SETS, IG.ALLOCATED_QTY_STORE, IG.SOLD_QTY, IG.CURRENT_STORE_INV, IG.CURRENT_WH_INV, IG.CURRENT_WH_FULL_SET_COUNT, IG.CURRENT_WH_FULL_SIZE_QTY, IG.CURRENT_WH_CUT_SIZE_QTY, IG.INWARD_SKU_GRADE, GG.GRADE AS GRAIN_GRADE, MG.MRP_BUCKET_GRADE FROM inward_grading IG LEFT JOIN grain_grading GG ON TRIM(CAST(IG.BRANCH_CODE AS VARCHAR)) = TRIM(CAST(GG.BRANCH_CODE AS VARCHAR)) AND LOWER(TRIM(IG.CATEGORY)) = GG.CATEGORY AND ( LOWER(NULLIF(TRIM(IG.META_1), \'\')) = GG.META1 OR ( NULLIF(TRIM(IG.META_1), \'\') IS NULL AND GG.META1 IS NULL ) ) AND ( LOWER(NULLIF(TRIM(IG.META_2), \'\')) = GG.META2 OR ( NULLIF(TRIM(IG.META_2), \'\') IS NULL AND GG.META2 IS NULL ) ) AND ( LOWER(NULLIF(TRIM(IG.META_3), \'\')) = GG.META3 OR ( NULLIF(TRIM(IG.META_3), \'\') IS NULL AND GG.META3 IS NULL ) ) LEFT JOIN mrp_bucket_grading MG ON TRIM(CAST(IG.BRANCH_CODE AS VARCHAR)) = TRIM(CAST(MG.BRANCH_CODE AS VARCHAR)) AND UPPER(TRIM(IG.SKU_GROUP)) = UPPER(TRIM(MG.SKU_GROUP)) AND LOWER(TRIM(IG.CATEGORY)) = LOWER(TRIM(MG.CATEGORY_MAPPED)) AND LOWER(TRIM(IG.L1_CAT)) = LOWER(TRIM(MG.L1_CATEGORY)) AND ( LOWER(NULLIF(TRIM(IG.META_1), \'\')) = LOWER(NULLIF(TRIM(MG.META1), \'\')) OR ( NULLIF(TRIM(IG.META_1), \'\') IS NULL AND NULLIF(TRIM(MG.META1), \'\') IS NULL ) ) AND ( LOWER(NULLIF(TRIM(IG.META_2), \'\')) = LOWER(NULLIF(TRIM(MG.META2), \'\')) OR ( NULLIF(TRIM(IG.META_2), \'\') IS NULL AND NULLIF(TRIM(MG.META2), \'\') IS NULL ) ) AND ( LOWER(NULLIF(TRIM(IG.META_3), \'\')) = LOWER(NULLIF(TRIM(MG.META3), \'\')) OR ( NULLIF(TRIM(IG.META_3), \'\') IS NULL AND NULLIF(TRIM(MG.META3), \'\') IS NULL ) ) ), scored AS ( SELECT *, CASE UPPER(TRIM(MRP_BUCKET_GRADE)) WHEN \'A\' THEN 4 WHEN \'B\' THEN 3 WHEN \'C\' THEN 2 WHEN \'D\' THEN 1 END AS MRP_GRADE_SCORE, CASE UPPER(TRIM(GRAIN_GRADE)) WHEN \'A\' THEN 4 WHEN \'B\' THEN 3 WHEN \'C\' THEN 2 WHEN \'D\' THEN 1 END AS GRAIN_GRADE_SCORE FROM final_base ), final_store_level AS ( SELECT BRANCH_CODE, STORE_NAME, REGION, SKU_GROUP, LIVE_DATE, CATEGORY, MRP_BUCKET, L1_CAT, META_1, META_2, META_3, INWARDED_FULL_SETS_QTY, INWARDED_FULL_SIZE_SETS, ALLOCATED_QTY_STORE, SOLD_QTY, CURRENT_STORE_INV, CURRENT_WH_INV, CURRENT_WH_FULL_SET_COUNT, CURRENT_WH_FULL_SIZE_QTY, CURRENT_WH_CUT_SIZE_QTY, INWARD_SKU_GRADE, GRAIN_GRADE, MRP_BUCKET_GRADE, CASE WHEN GRAIN_GRADE_SCORE IS NULL OR MRP_GRADE_SCORE IS NULL THEN NULL WHEN ( GRAIN_GRADE_SCORE + MRP_GRADE_SCORE ) / 2.0 = 4 THEN \'A\' WHEN ( GRAIN_GRADE_SCORE + MRP_GRADE_SCORE ) / 2.0 >= 3 THEN \'B\' WHEN ( GRAIN_GRADE_SCORE + MRP_GRADE_SCORE ) / 2.0 >= 2 THEN \'C\' ELSE \'D\' END AS FINAL_GRADE FROM scored ), sku_master AS ( SELECT SKU_GROUP, MAX(INWARD_SKU_GRADE) AS INWARD_GRADE, MAX(CATEGORY) AS CATEGORY, MAX(L1_CAT) AS L1_CAT, MAX(META_1) AS META_1, MAX(META_2) AS META_2, MAX(META_3) AS META_3, MAX(MRP_BUCKET) AS MRP_BUCKET, MAX(CURRENT_WH_INV) AS WH_LEFT_INV, MAX(CURRENT_WH_FULL_SET_COUNT) AS WH_LEFT_OPS FROM final_store_level GROUP BY SKU_GROUP ), existing_allocation AS ( SELECT SKU_GROUP, BRANCH_CODE, MAX( CASE WHEN COALESCE(ALLOCATED_QTY_STORE, 0) > 0 THEN 1 ELSE 0 END ) AS ALREADY_SUPPLIED, SUM( COALESCE(ALLOCATED_QTY_STORE, 0) ) AS ALLOCATED_QTY_STORE FROM final_store_level GROUP BY SKU_GROUP, BRANCH_CODE ), potential_store_base AS ( SELECT SM.SKU_GROUP, SM.INWARD_GRADE, SM.CATEGORY, SM.L1_CAT, SM.META_1, SM.META_2, SM.META_3, SM.MRP_BUCKET, GG.BRANCH_CODE, GG.GRADE AS GRAIN_GRADE, MSG.MRP_BUCKET_GRADE, COALESCE( EA.ALREADY_SUPPLIED, 0 ) AS ALREADY_SUPPLIED, COALESCE( EA.ALLOCATED_QTY_STORE, 0 ) AS ALLOCATED_QTY_STORE, SM.WH_LEFT_INV, SM.WH_LEFT_OPS FROM sku_master SM INNER JOIN grain_grading GG ON LOWER(TRIM(SM.CATEGORY)) = GG.CATEGORY AND ( LOWER(NULLIF(TRIM(SM.META_1), \'\')) = GG.META1 OR ( NULLIF(TRIM(SM.META_1), \'\') IS NULL AND GG.META1 IS NULL ) ) AND ( LOWER(NULLIF(TRIM(SM.META_2), \'\')) = GG.META2 OR ( NULLIF(TRIM(SM.META_2), \'\') IS NULL AND GG.META2 IS NULL ) ) AND ( LOWER(NULLIF(TRIM(SM.META_3), \'\')) = GG.META3 OR ( NULLIF(TRIM(SM.META_3), \'\') IS NULL AND GG.META3 IS NULL ) ) LEFT JOIN mrp_store_grain MSG ON TRIM(CAST(GG.BRANCH_CODE AS VARCHAR)) = TRIM(CAST(MSG.BRANCH_CODE AS VARCHAR)) AND LOWER(TRIM(SM.CATEGORY)) = MSG.CATEGORY AND LOWER(TRIM(SM.L1_CAT)) = MSG.L1_CATEGORY AND ( LOWER(NULLIF(TRIM(SM.META_1), \'\')) = MSG.META1 OR ( NULLIF(TRIM(SM.META_1), \'\') IS NULL AND MSG.META1 IS NULL ) ) AND ( LOWER(NULLIF(TRIM(SM.META_2), \'\')) = MSG.META2 OR ( NULLIF(TRIM(SM.META_2), \'\') IS NULL AND MSG.META2 IS NULL ) ) AND ( LOWER(NULLIF(TRIM(SM.META_3), \'\')) = MSG.META3 OR ( NULLIF(TRIM(SM.META_3), \'\') IS NULL AND MSG.META3 IS NULL ) ) AND SM.MRP_BUCKET = MSG.MRP_BUCKET LEFT JOIN existing_allocation EA ON UPPER(TRIM(SM.SKU_GROUP)) = UPPER(TRIM(EA.SKU_GROUP)) AND TRIM(CAST(GG.BRANCH_CODE AS VARCHAR)) = TRIM(CAST(EA.BRANCH_CODE AS VARCHAR)) ), potential_store_scored AS ( SELECT *, CASE UPPER(TRIM(GRAIN_GRADE)) WHEN \'A\' THEN 4 WHEN \'B\' THEN 3 WHEN \'C\' THEN 2 WHEN \'D\' THEN 1 END AS GRAIN_SCORE, CASE UPPER(TRIM(MRP_BUCKET_GRADE)) WHEN \'A\' THEN 4 WHEN \'B\' THEN 3 WHEN \'C\' THEN 2 WHEN \'D\' THEN 1 END AS MRP_SCORE FROM potential_store_base ), potential_store_final AS ( SELECT *, CASE WHEN GRAIN_SCORE IS NULL OR MRP_SCORE IS NULL THEN NULL WHEN ( GRAIN_SCORE + MRP_SCORE ) / 2.0 = 4 WHEN ( GRAIN_SCORE + MRP_SCORE ) / 2.0 >= 3 THEN \'B\' WHEN ( GRAIN_SCORE + MRP_SCORE ) / 2.0 >= 2 THEN \'C\' ELSE \'D\' END AS POTENTIAL_FINAL_GRADE FROM potential_store_scored ), opportunity_count AS ( SELECT SKU_GROUP, COUNT( DISTINCT CASE WHEN POTENTIAL_FINAL_GRADE = \'A\' AND ALREADY_SUPPLIED = 0 THEN BRANCH_CODE END ) AS A_NOT_SUPPLIED, COUNT( DISTINCT CASE WHEN POTENTIAL_FINAL_GRADE = \'B\' AND ALREADY_SUPPLIED = 0 THEN BRANCH_CODE END ) AS B_NOT_SUPPLIED, COUNT( DISTINCT CASE WHEN POTENTIAL_FINAL_GRADE = \'C\' AND ALREADY_SUPPLIED = 0 THEN BRANCH_CODE END ) AS C_NOT_SUPPLIED, COUNT( DISTINCT CASE WHEN POTENTIAL_FINAL_GRADE = \'D\' AND ALREADY_SUPPLIED = 0 THEN BRANCH_CODE END ) AS D_NOT_SUPPLIED FROM potential_store_final GROUP BY SKU_GROUP ), sku_pivot AS ( SELECT SKU_GROUP, MAX(INWARD_SKU_GRADE) AS INWARD_GRADE, MAX(CATEGORY) AS CAT, MAX(META_1) AS META1, MAX(META_2) AS META2, MAX(META_3) AS META3, MAX(MRP_BUCKET) AS MRP_BUCKET, MAX(LIVE_DATE) AS LIVE_DATE, SUM( CASE WHEN FINAL_GRADE = \'A\' THEN COALESCE(ALLOCATED_QTY_STORE, 0) ELSE 0 END ) AS A_QTY, COUNT( DISTINCT CASE WHEN FINAL_GRADE = \'A\' AND COALESCE(ALLOCATED_QTY_STORE, 0) > 0 THEN BRANCH_CODE END ) AS A_OPS, SUM( CASE WHEN FINAL_GRADE = \'B\' THEN COALESCE(ALLOCATED_QTY_STORE, 0) ELSE 0 END ) AS B_QTY, COUNT( DISTINCT CASE WHEN FINAL_GRADE = \'B\' AND COALESCE(ALLOCATED_QTY_STORE, 0) > 0 THEN BRANCH_CODE END ) AS B_OPS, SUM( CASE WHEN FINAL_GRADE = \'C\' THEN COALESCE(ALLOCATED_QTY_STORE, 0) ELSE 0 END ) AS C_QTY, COUNT( DISTINCT CASE WHEN FINAL_GRADE = \'C\' AND COALESCE(ALLOCATED_QTY_STORE, 0) > 0 THEN BRANCH_CODE END ) AS C_OPS, SUM( CASE WHEN FINAL_GRADE = \'D\' THEN COALESCE(ALLOCATED_QTY_STORE, 0) ELSE 0 END ) AS D_QTY, COUNT( DISTINCT CASE WHEN FINAL_GRADE = \'D\' AND COALESCE(ALLOCATED_QTY_STORE, 0) > 0 THEN BRANCH_CODE END ) AS D_OPS, MAX(CURRENT_WH_INV) AS WH_LEFT_INV, MAX(CURRENT_WH_FULL_SET_COUNT) AS WH_LEFT_OPS FROM final_store_level GROUP BY SKU_GROUP ), combined AS ( SELECT SP.*, COALESCE( OC.A_NOT_SUPPLIED, 0 ) AS A_NOT_SUPPLIED, COALESCE( OC.B_NOT_SUPPLIED, 0 ) AS B_NOT_SUPPLIED, COALESCE( OC.C_NOT_SUPPLIED, 0 ) AS C_NOT_SUPPLIED, COALESCE( OC.D_NOT_SUPPLIED, 0 ) AS D_NOT_SUPPLIED FROM sku_pivot SP LEFT JOIN opportunity_count OC ON UPPER(TRIM(SP.SKU_GROUP)) = UPPER(TRIM(OC.SKU_GROUP)) ), supply_calc_a AS ( SELECT *, LEAST( COALESCE(WH_LEFT_OPS, 0), A_NOT_SUPPLIED ) AS A_CAN_SUPPLY FROM combined ), supply_calc_b AS ( SELECT *, LEAST( GREATEST( COALESCE(WH_LEFT_OPS, 0) - A_CAN_SUPPLY, 0 ), B_NOT_SUPPLIED ) AS B_CAN_SUPPLY FROM supply_calc_a ), supply_calc_c AS ( SELECT *, LEAST( GREATEST( COALESCE(WH_LEFT_OPS, 0) - A_CAN_SUPPLY - B_CAN_SUPPLY, 0 ), C_NOT_SUPPLIED ) AS C_CAN_SUPPLY FROM supply_calc_b ), supply_calc_d AS ( SELECT *, LEAST( GREATEST( COALESCE(WH_LEFT_OPS, 0) - A_CAN_SUPPLY - B_CAN_SUPPLY - C_CAN_SUPPLY, 0 ), D_NOT_SUPPLIED ) AS D_CAN_SUPPLY FROM supply_calc_c ) SELECT SKU_GROUP, LIVE_DATE, INWARD_GRADE, CAT, META1, META2, META3, MRP_BUCKET, A_QTY, A_OPS, B_QTY, B_OPS, C_QTY, C_OPS, D_QTY, D_OPS, WH_LEFT_INV, WH_LEFT_OPS, A_NOT_SUPPLIED, B_NOT_SUPPLIED, C_NOT_SUPPLIED, D_NOT_SUPPLIED, A_CAN_SUPPLY AS A, B_CAN_SUPPLY AS B, C_CAN_SUPPLY AS C, D_CAN_SUPPLY AS D FROM supply_calc_d ORDER BY SKU_GROUP;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            